// Loads the game's Pokémon art bundle (src/content/art.json, generated by
// scripts/build-content.mjs): PMD SpriteCollab atlases with per-frame anchors, portraits and
// PokeAPI cries. Every species goes through the same path as any other creature art:
// decode -> clips via the fallback table -> registry record -> cry bank.
import { SPECIES_BY_ID } from '../rules/species';
import type { CreatureArt } from './art';
import { cries } from './cries';
import { buildArt, type PackSpecies } from './pack';
import { registry } from './registry';

export interface ArtBundle {
  generated: string;
  notice?: string;
  licenses?: { scope: string; name: string; url?: string; holder?: string; note?: string }[];
  species: Record<string, { art: PackSpecies['art']; cry?: PackSpecies['cry']; provenance?: PackSpecies['provenance'] }>;
}

export async function loadBuiltinArt(bundle: ArtBundle, onArt: (id: string, art: CreatureArt) => void, onProgress?: (f: number) => void) {
  const ids = Object.keys(bundle.species);
  let k = 0;
  for (const id of ids) {
    const entry = bundle.species[id];
    const sp = SPECIES_BY_ID[id];
    const { art, report, notes } = await buildArt(id, entry.art);
    registry.setArt(id, art);
    onArt(id, art);
    if (entry.cry?.src) cries.sample(id, entry.cry.src, entry.cry.gain ?? 1, entry.cry.alt, sp?.height ?? 1.2, sp?.elements[0] ?? 'plain');
    else { cries.synth(id, sp?.height ?? 1.2, sp?.elements[0] ?? 'plain'); notes.push('no cry; using a synthesised call'); }
    const credits = entry.art.credits ?? [];
    registry.record({
      id, name: sp?.name ?? id, origin: 'pokedex',
      data: { source: entry.provenance?.data ?? 'PokéAPI', license: entry.provenance?.dataLicense ?? 'PokéAPI' },
      art: { kind: 'pmd', source: entry.art.source, license: entry.art.license ?? 'CC BY-NC 4.0', credits, url: entry.art.url, clips: report },
      cry: { kind: entry.cry?.src ? 'sample' : 'synth', source: entry.cry?.source ?? 'synthesised', license: entry.cry?.license ?? '—', era: entry.cry?.era, alt: entry.cry?.altSource },
      status: notes.length ? 'fallback' : 'ok', notes, checksum: entry.provenance?.sha256?.atlas,
    });
    onProgress?.(++k / ids.length);
    if (k % 4 === 0) await new Promise((r) => setTimeout(r, 0));
  }
  registry.addPack({ id: 'pokedex', name: 'Pokémon', species: ids, moves: 0, created: bundle.generated, notice: bundle.notice, licenses: bundle.licenses ?? [] });
}
